// dsh-lean-router - bundle 构建（票 02；分片合并版：主模板 + 各层 frag-*.patch.yml 固定顺序）
// 组装：HEADER + presets/base/lean-router.patch.yml + 存在的 frag-lean/frag-toolface/frag-router -> cordis.patch.yml
// 顶层为 YAML 块序列，后续 - insert/... 项自然续接；集成时由 master 用宿主 --dump-config 复验。
import { readFile, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = fileURLToPath(new URL("..", import.meta.url));
const SRC = join(ROOT, "presets", "base", "lean-router.patch.yml");
const OUT = join(ROOT, "cordis.patch.yml");
const FRAGMENTS = ["frag-lean.patch.yml", "frag-toolface.patch.yml", "frag-router.patch.yml", "frag-preset.patch.yml"];
const HEADER = [
  "# dsh-lean-router cordis.patch.yml",
  "# Generated by scripts/build-bundle.mjs - do not edit by hand.",
  "# base: presets/base/lean-router.patch.yml + fragments: " + FRAGMENTS.join(", "),
  "",
].join("\n");

export async function build() {
  let out = HEADER + (await readFile(SRC, "utf8"));
  for (const f of FRAGMENTS) {
    const p = join(ROOT, "presets", "base", f);
    if (existsSync(p)) {
      let frag = await readFile(p, "utf8");
      if (!frag.endsWith("\n")) frag += "\n";
      out += frag;
    }
  }
  await writeFile(OUT, out, "utf8");
  return out;
}

export async function check() {
  const regen = await build();
  const cur = await readFile(OUT, "utf8");
  return regen === cur;
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const ok = await check();
  console.log(ok ? "[build --check] PASS（cordis.patch.yml 反向逐字节一致）" : "[build --check] FAIL：与再生成结果不一致，运行 npm run build 更新");
  process.exit(ok ? 0 : 1);
}
